```csharp
namespace sv_58ea0fd9c6ab44cba186db816948dafa.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "WH-001";
    public string SelectedWarehouseName => Warehouses.First(w => w.Id == SelectedWarehouseId).Name;

    public event Action? OnChange;

    public static readonly (string Id, string Name)[] Warehouses =
    [
        ("WH-001", "Warehouse A — Main Distribution"),
        ("WH-002", "Warehouse B — East Regional"),
        ("WH-003", "Warehouse C — West Coast"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}
```

#### 2. `Services/InventoryAlertService.cs`
Scoped service that simulates a DB query for low-stock count AND holds current alert count with a change event so all subscribers update together.

```csharp
namespace sv_58ea0fd9c6ab44cba186db816948dafa.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}
```

