#### 9. Create `Components/Pages/Dashboard.razor`
The dashboard page that owns the polling timer. It starts polling on initialization, stops on dispose. When the warehouse changes, it immediately refreshes and continues polling for the new warehouse.

```razor
@page "/dashboard"
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>📊 Warehouse Dashboard</h1>
<p class="text-muted">Monitoring: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="card mt-4" style="max-width: 400px;">
    <div class="card-body text-center">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4 @(AlertService.CurrentAlertCount > 0 ? "text-danger" : "text-success")">
            @AlertService.CurrentAlertCount
        </p>
        <p class="text-muted">items below minimum stock level</p>
        <p class="small text-muted">Auto-refreshes every 10 seconds</p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await RestartPollingAsync();
            StateHasChanged();
        });
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial fetch and start polling
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose or warehouse change
        }
    }

    private async Task RestartPollingAsync()
    {
        // Stop existing polling
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
        _timer?.Dispose();

        // Fetch immediately for new warehouse, then restart
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        StartPolling();
    }

    public async ValueTask DisposeAsync()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
        _timer?.Dispose();
    }
}
```

